<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { products, findSku, money, type Category } from '../domain/catalog'
import { availability, calculate, coupons, demoAddresses, type CouponCode } from '../domain/commerce'
import { useShop } from '../stores/shop'
import ProductArt from './ProductArt.vue'
import AppButton from './AppButton.vue'
type Screen='catalog'|'product'|'cart'|'checkout'|'orders'
const props=withDefaults(defineProps<{screen?:Screen;productId?:string}>(),{screen:'catalog',productId:'cup'})
const shop=useShop()
const query=ref(''),category=ref<Category>('全部'),sort=ref('featured'),stockOnly=ref(false),selectedSku=ref(''),quantity=ref(1),notice=ref(''),error=ref(''),loading=ref(true),catalogError=ref(false),simulateFailure=ref(false),submitted=ref(false),resetConfirm=ref(false)
let noticeTimer: ReturnType<typeof setTimeout>|undefined
const requestKey=`demo-${Date.now()}-${Math.random().toString(36).slice(2)}`
const categories:Category[]=['全部','器物','出行','桌面']
const product=computed(()=>products.find(item=>item.id===props.productId)??products[0])
const sku=computed(()=>product.value.skus.find(item=>item.id===selectedSku.value)??product.value.skus[0])
const stock=computed(()=>availability(sku.value.id,shop.state.orders))
const cartCount=computed(()=>shop.state.cart.reduce((sum,line)=>sum+line.quantity,0))
const cartLines=computed(()=>shop.state.cart.map(line=>({...line,...findSku(line.skuId)!})))
const totals=computed(()=>calculate(shop.state.cart,shop.state.coupon))
const allSelected=computed(()=>shop.state.cart.length>0&&shop.state.cart.every(line=>line.selected))
const address=computed(()=>demoAddresses.find(item=>item.id===shop.state.addressId)??demoAddresses[0])
const filteredProducts=computed(()=>{
  const result=products.filter(item=>(category.value==='全部'||item.category===category.value)&&`${item.name} ${item.subtitle}`.toLowerCase().includes(query.value.trim().toLowerCase())&&(!stockOnly.value||item.skus.some(option=>availability(option.id,shop.state.orders)>0)))
  if(sort.value==='low')result.sort((a,b)=>a.skus[0].price-b.skus[0].price)
  if(sort.value==='high')result.sort((a,b)=>b.skus[0].price-a.skus[0].price)
  return result
})
const completedCount=computed(()=>shop.state.orders.filter(order=>order.status==='已完成').length)
onMounted(()=>{
  setTimeout(()=>loading.value=false,250)
  // #ifdef H5
  // uni-input places ARIA attributes on its host; name the native editable element too.
  document.querySelectorAll('.search-wrap input').forEach(input=>input.setAttribute('aria-label','搜索商品'))
  // #endif
})
function flash(message:string){notice.value=message;if(noticeTimer)clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',3500)}
function run(action:()=>void){error.value='';try{action()}catch(reason){error.value=reason instanceof Error?reason.message:'操作失败，请重试'}}
function go(screen:Screen,id='cup') {error.value='';if(screen===props.screen&&screen!=='product')return;const path=screen==='catalog'?'index':screen;uni.navigateTo({url:`/pages/${path}/${path}${screen==='product'?`?id=${id}`:''}`,fail:()=>uni.reLaunch({url:'/pages/index/index'})})}
function home(){uni.reLaunch({url:'/pages/index/index'})}
function addToCart(){run(()=>{shop.add(sku.value.id,quantity.value);flash('已加入购物袋，规格与数量已保存')})}
function selectSku(id:string){selectedSku.value=id;quantity.value=1;error.value=''}
function toggleAll(){const selected=!allSelected.value;shop.state.cart.forEach(line=>line.selected=selected)}
function setCoupon(code:CouponCode){shop.state.coupon=code;error.value=''}
function resetFilters(){query.value='';category.value='全部';sort.value='featured';stockOnly.value=false}
function reloadCatalog(){catalogError.value=false;loading.value=true;setTimeout(()=>loading.value=false,450)}
async function submitOrder(){
  if(submitted.value||shop.submitting)return
  error.value=''
  try{await shop.submit(requestKey,simulateFailure.value);submitted.value=true;simulateFailure.value=false;flash('模拟订单创建成功，没有发生真实付款')}catch(reason){error.value=reason instanceof Error?reason.message:'提交失败，请重试'}
}
function resetDemo(){shop.reset();resetConfirm.value=false;flash('演示数据已重置，库存已恢复')}
function backToPortfolio(){
  // #ifdef H5
  window.location.href=new URL('../',window.location.href.split('#')[0]).href
  // #endif
  // #ifndef H5
  flash('作品集请访问 Callmecx 的 GitHub 项目主页')
  // #endif
}
</script>

<template>
  <view class="shop-shell">
    <view class="demo-strip"><text>CHENXI DEVLAB · 交互作品 01</text><text class="demo-pill">演示商城 · 无真实交易</text></view>
    <view class="site-header">
      <AppButton class="brand" aria-description="返回 ShopPilot 首页" @click="home"><view class="brand-mark">s.</view><view><text class="brand-name">ShopPilot</text><text class="brand-sub">把日常，过得刚刚好</text></view></AppButton>
      <view class="desktop-nav"><AppButton :class="{active:screen==='catalog'}" @click="home">发现好物</AppButton><AppButton :class="{active:screen==='orders'}" @click="go('orders')">我的订单</AppButton><AppButton class="portfolio-link" @click="backToPortfolio">返回作品集 ↗</AppButton></view>
      <AppButton class="bag-button" data-testid="open-cart" @click="go('cart')"><text class="bag-symbol">♧</text><text>购物袋</text><text class="bag-count">{{ cartCount }}</text></AppButton>
    </view>
    <view v-if="shop.storageWarning" class="alert warning" role="status">{{ shop.storageWarning }}</view>
    <view v-if="notice" class="toast" role="status">✓ {{ notice }}</view>

    <view v-if="screen==='catalog'" class="catalog-page" role="main">
      <view class="hero">
        <view class="hero-copy"><view class="eyebrow"><view class="tiny-line" /> EVERYDAY, WELL MADE.</view><text class="hero-title" role="heading" aria-level="1">让日常好物，<br>陪你慢下来。</text><text class="hero-desc">一只喜欢的杯子，一束温柔的光。<br>从认真挑选的小物开始，找回生活的质感。</text><AppButton class="hero-link" @click="category='器物'">探索器物系列 <text>↗</text></AppButton><view class="hero-note"><view class="tiny-star">✳</view><text>少一点将就 · 多一点喜欢</text></view></view>
        <view class="hero-visual"><view class="hero-arc" /><view class="hero-art-back"><ProductArt kind="lamp" color="#ddd1b9" backdrop="#cbd2bd" /></view><view class="hero-art-front"><ProductArt kind="cup" color="#b77959" backdrop="#dfd6bd" /></view><view class="visual-label"><text>THE SLOW LIVING EDIT</text><text class="visual-number">01 / 06</text></view><view class="hero-sticker"><text>好好生活</text><text>GOOD DAYS</text></view></view>
      </view>
      <view class="benefits"><text>✧ 原创虚构商品</text><text>◉ 满 ¥299 模拟包邮</text><text>↻ 本地保存 · 随时继续</text></view>
      <view class="section-title"><view><text class="eyebrow">CURATED FOR YOUR EVERYDAY</text><text class="title" role="heading" aria-level="2">日常精选<text class="title-count"> / 06</text></text></view><text class="section-sub">有用、有趣，也有一点温度。</text></view>
      <view class="catalog-controls"><view class="category-list"><AppButton v-for="item in categories" :key="item" :class="['category',{selected:category===item}]" :aria-pressed="category===item" @click="category=item">{{ item }}</AppButton></view><view class="search-wrap"><text>⌕</text><input v-model="query" placeholder="搜索你心里的好物" aria-label="搜索商品" confirm-type="search"><AppButton v-if="query" aria-label="清除搜索" @click="query=''">×</AppButton></view></view>
      <view class="filter-row"><text>{{ filteredProducts.length }} 件精选好物</text><view class="filter-actions"><AppButton :class="{selected:stockOnly}" :aria-pressed="stockOnly" @click="stockOnly=!stockOnly">{{ stockOnly?'✓':'○' }} 仅看有货</AppButton><AppButton aria-description="点击切换推荐、价格升序或降序" @click="sort=sort==='featured'?'low':sort==='low'?'high':'featured'">{{ sort==='featured'?'推荐排序':sort==='low'?'价格从低到高':'价格从高到低' }} ↕</AppButton></view></view>
      <view v-if="loading" class="product-grid" aria-label="商品加载中"><view v-for="n in 6" :key="n" class="skeleton"><view /><text>正在挑选好物…</text></view></view>
      <view v-else-if="catalogError" class="empty-state"><text class="empty-icon">↻</text><text class="title">好物暂时没加载出来</text><text>这是模拟加载异常，可点击重试恢复。</text><AppButton class="primary" @click="reloadCatalog">重新加载商品</AppButton></view>
      <view v-else-if="!filteredProducts.length" class="empty-state"><text class="empty-icon">⌕</text><text class="title">没有找到这件好物</text><text>换一个关键词，或看看其他分类。</text><AppButton class="primary" @click="resetFilters">清除全部筛选</AppButton></view>
      <view v-else class="product-grid"><AppButton v-for="item in filteredProducts" :key="item.id" class="product-card" :data-testid="`product-${item.id}`" @click="go('product',item.id)"><view class="product-image"><ProductArt :kind="item.art" :backdrop="item.backdrop" :color="item.skus[0].color" /><text class="product-label">{{ item.label }}</text><view class="product-plus">↗</view></view><view class="product-info"><text class="product-category">{{ item.category }} / DAILY ESSENTIALS</text><text class="product-name">{{ item.name }}</text><text class="product-subtitle">{{ item.subtitle }}</text><view class="product-bottom"><text class="price">¥{{ money(item.skus[0].price) }}<text class="from"> 起</text></text><view class="swatches"><view v-for="option in item.skus" :key="option.id" :style="{background:option.color}" /></view></view></view></AppButton></view>
      <view class="editorial"><text class="editorial-symbol">✳</text><view><text class="editorial-title">好的生活，不必很复杂。</text><text>用少而好的选择，创造属于自己的日常。</text></view><text class="editorial-index">SHOPPILOT<br>DAILY JOURNAL</text></view>
      <view class="demo-tools"><text>工程体验：可主动验证异常恢复</text><AppButton @click="catalogError=!catalogError">{{ catalogError?'恢复商品列表':'模拟加载失败' }}</AppButton></view>
    </view>

    <view v-else-if="screen==='product'" class="inner-page" role="main">
      <AppButton class="back-link" @click="home">← 返回日常精选</AppButton>
      <view class="detail-grid"><view class="detail-image"><ProductArt :kind="product.art" :backdrop="product.backdrop" :color="sku.color" /><text class="detail-caption">原创 CSS 商品插画 · 演示商品</text></view><view class="detail-info"><text class="eyebrow">{{ product.category }} / EVERYDAY ESSENTIALS</text><text class="detail-title" role="heading" aria-level="1">{{ product.name }}</text><text class="detail-subtitle">{{ product.subtitle }}</text><text class="detail-price">¥{{ money(sku.price) }}</text><view class="detail-divider" /><text class="field-label">选择颜色 <text class="muted">/ {{ sku.name }}</text></text><view class="sku-options"><AppButton v-for="option in product.skus" :key="option.id" :class="['sku-button',{chosen:sku.id===option.id,soldout:availability(option.id,shop.state.orders)===0}]" :aria-label="`选择${option.name}`" :aria-pressed="sku.id===option.id" @click="selectSku(option.id)"><view class="sku-dot" :style="{background:option.color}" />{{ option.name }}<text v-if="!availability(option.id,shop.state.orders)"> · 售罄</text></AppButton></view><view class="quantity-row"><text class="field-label">数量</text><view class="stepper"><AppButton :disabled="quantity<=1" aria-label="减少购买数量" @click="quantity--">−</AppButton><text>{{ quantity }}</text><AppButton :disabled="quantity>=stock" aria-label="增加购买数量" @click="quantity++">+</AppButton></view><text class="stock" :class="{'stock-low':stock<4}">{{ stock?`库存 ${stock} 件`:'当前规格已售罄' }}</text></view><view v-if="error" class="alert" role="alert">{{ error }}</view><AppButton class="primary add-button" :disabled="!stock" data-testid="add-to-cart" @click="addToCart">{{ stock?'加入购物袋':'该规格暂时售罄' }}<text>＋</text></AppButton><AppButton class="secondary" @click="go('cart')">查看购物袋 · {{ cartCount }} 件</AppButton><view class="detail-description"><text class="field-label">关于这件好物</text><text>{{ product.description }}</text><view class="spec-tags"><text v-for="spec in product.specs" :key="spec">{{ spec }}</text></view></view></view></view>
    </view>

    <view v-else-if="screen==='cart'" class="inner-page" role="main">
      <view class="page-title"><text class="eyebrow">YOUR LITTLE COLLECTION</text><text class="title" role="heading" aria-level="1">喜欢的，都在这里。<text class="title-count"> / {{ cartCount }}</text></text><text class="muted">购物袋会自动保存在当前设备，回来时继续挑选。</text></view>
      <view v-if="!cartLines.length" class="empty-state"><text class="empty-icon">♧</text><text class="title">购物袋还空着</text><text>去挑一件让日常更舒心的小物吧。</text><AppButton class="primary" @click="home">发现日常好物 ↗</AppButton></view>
      <view v-else class="checkout-grid"><view class="cart-list"><AppButton class="select-all" :aria-pressed="allSelected" @click="toggleAll"><text class="checkmark">{{ allSelected?'✓':'○' }}</text> 全选商品</AppButton><view v-for="line in cartLines" :key="line.skuId" class="cart-line"><AppButton class="line-check" :aria-label="`勾选${line.product.name}${line.sku.name}`" :aria-pressed="line.selected" @click="shop.toggle(line.skuId)">{{ line.selected?'✓':'○' }}</AppButton><AppButton class="cart-art" :aria-label="`查看${line.product.name}`" @click="go('product',line.product.id)"><ProductArt :kind="line.product.art" :color="line.sku.color" :backdrop="line.product.backdrop" /></AppButton><view class="cart-description"><text class="cart-name">{{ line.product.name }}</text><text class="muted">{{ line.sku.name }} · 库存 {{ availability(line.skuId,shop.state.orders) }}</text><text class="price">¥{{ money(line.sku.price) }}</text><view class="cart-line-bottom"><view class="stepper"><AppButton :disabled="line.quantity<=1" :aria-label="`减少${line.sku.name}数量`" @click="run(()=>shop.quantity(line.skuId,line.quantity-1))">−</AppButton><text>{{ line.quantity }}</text><AppButton :disabled="line.quantity>=availability(line.skuId,shop.state.orders)" :aria-label="`增加${line.sku.name}数量`" @click="run(()=>shop.quantity(line.skuId,line.quantity+1))">+</AppButton></view><AppButton class="remove-button" :aria-label="`移除${line.product.name}${line.sku.name}`" @click="shop.remove(line.skuId)">移除</AppButton></view></view></view><AppButton class="back-link" @click="home">← 再逛一会儿</AppButton></view><view class="summary-card"><text class="summary-title">这一袋，小确幸。</text><view class="summary-row"><text>已选商品 · {{ totals.count }} 件</text><text>¥{{ money(totals.subtotal) }}</text></view><text class="field-label">你的专属礼遇</text><view class="coupon-list"><AppButton v-for="coupon in coupons" :key="coupon.code" :class="['coupon',{chosen:shop.state.coupon===coupon.code}]" :aria-pressed="shop.state.coupon===coupon.code" @click="setCoupon(coupon.code)">{{ shop.state.coupon===coupon.code?'●':'○' }} {{ coupon.name }}</AppButton></view><view v-if="!totals.eligible" class="alert" role="alert">未达到优惠券使用门槛，请更换优惠券。</view><view class="summary-row"><text>优惠减免</text><text class="terracotta">− ¥{{ money(totals.discount) }}</text></view><view class="summary-row"><text>模拟运费</text><text>{{ totals.shipping?`¥${money(totals.shipping)}`:'免运费' }}</text></view><text class="summary-note">优惠前商品满 ¥299 免运费，否则 ¥12</text><view class="summary-total"><text>预计合计</text><text>¥{{ money(totals.total) }}</text></view><view v-if="error" class="alert" role="alert">{{ error }}</view><AppButton class="primary" :disabled="!totals.count||!totals.eligible" data-testid="checkout" @click="go('checkout')">确认订单 <text>→</text></AppButton><text class="summary-note centered">仅模拟下单，不会收取任何费用</text></view></view>
    </view>

    <view v-else-if="screen==='checkout'" class="inner-page" role="main">
      <view v-if="submitted" class="success-panel"><view class="success-icon">✓</view><text class="eyebrow">A LITTLE JOY IS ON ITS WAY</text><text class="title" role="heading" aria-level="1">好物，已在期待中。</text><text>模拟订单创建成功，库存与购物袋已同步更新。</text><text class="muted">未发生真实付款，也不会真实发货。</text><AppButton class="primary" data-testid="view-orders" @click="go('orders')">查看我的订单 →</AppButton><AppButton class="back-link" @click="home">继续发现日常好物</AppButton></view>
      <view v-else><AppButton class="back-link" @click="go('cart')">← 返回购物袋</AppButton><view class="page-title"><text class="eyebrow">ONE LAST LITTLE STEP</text><text class="title" role="heading" aria-level="1">确认这份小期待。</text><text class="muted">此处仅使用预设虚拟地址，不采集真实姓名、电话或住址。</text></view><view class="checkout-grid"><view><view class="content-card"><text class="summary-title">送到哪里？</text><AppButton v-for="item in demoAddresses" :key="item.id" :class="['address-card',{chosen:shop.state.addressId===item.id}]" :aria-pressed="shop.state.addressId===item.id" @click="shop.state.addressId=item.id"><view class="address-heading"><text>{{ item.name }} <text class="address-tag">{{ item.label }}</text></text><text>{{ shop.state.addressId===item.id?'●':'○' }}</text></view><text>{{ item.address }}</text><text class="muted">{{ item.phone }}</text></AppButton></view><view class="content-card"><text class="summary-title">你的好物清单</text><view v-for="line in cartLines.filter(item=>item.selected)" :key="line.skuId" class="checkout-item"><text>{{ line.product.name }} · {{ line.sku.name }} × {{ line.quantity }}</text><text>¥{{ money(line.sku.price*line.quantity) }}</text></view><text v-if="!totals.count" class="alert">没有待结算商品，请返回购物袋。</text></view></view><view class="summary-card"><text class="summary-title">订单确认</text><text class="muted">{{ address.label }} · {{ address.name }}</text><view class="summary-row"><text>商品金额</text><text>¥{{ money(totals.subtotal) }}</text></view><view class="summary-row"><text>优惠减免</text><text>− ¥{{ money(totals.discount) }}</text></view><view class="summary-row"><text>模拟运费</text><text>¥{{ money(totals.shipping) }}</text></view><view class="summary-total"><text>模拟实付</text><text>¥{{ money(totals.total) }}</text></view><view v-if="error" class="alert" role="alert">{{ error }}</view><AppButton class="primary" :disabled="shop.submitting||!totals.count||!totals.eligible" data-testid="submit-order" @click="submitOrder">{{ shop.submitting?'正在创建模拟订单…':'提交模拟订单' }}<text v-if="!shop.submitting">→</text></AppButton><text class="summary-note centered">本地 Mock 服务 · 无支付接口 · 防重复提交</text><AppButton class="failure-toggle" :aria-pressed="simulateFailure" @click="simulateFailure=!simulateFailure">{{ simulateFailure?'✓':'○' }} 模拟本次提交失败（测试）</AppButton></view></view></view>
    </view>

    <view v-else-if="screen==='orders'" class="inner-page" role="main">
      <view class="page-title"><text class="eyebrow">YOUR EVERYDAY STORIES</text><text class="title" role="heading" aria-level="1">每一份期待，都有记录。</text><text class="muted">这些订单仅保存在当前设备。点击按钮可体验模拟物流状态。</text></view><view class="order-stats"><view><text>{{ shop.state.orders.length }}</text><text>模拟订单</text></view><view><text>{{ completedCount }}</text><text>已完成体验</text></view><view><text>¥{{ money(shop.state.orders.reduce((sum,order)=>sum+order.total,0)) }}</text><text>模拟订单合计</text></view></view>
      <view v-if="!shop.state.orders.length" class="empty-state"><text class="empty-icon">↗</text><text class="title">日常故事，从这里开始</text><text>完成一次模拟下单，即可查看订单与状态。</text><AppButton class="primary" @click="home">去发现好物</AppButton></view>
      <view v-for="order in shop.state.orders" :key="order.id" class="order-card"><view class="order-head"><view><text class="order-id">{{ order.id }}</text><text class="muted">{{ new Date(order.createdAt).toLocaleString('zh-CN') }}</text></view><text class="order-status">{{ order.status }}</text></view><view class="order-progress"><text :class="{done:true}">① 待发货</text><view /><text :class="{done:order.status!=='待发货'}">② 运输中</text><view /><text :class="{done:order.status==='已完成'}">③ 已完成</text></view><view v-for="line in order.lines" :key="line.skuId" class="order-item"><text>{{ findSku(line.skuId)?.product.name }} · {{ findSku(line.skuId)?.sku.name }}</text><text>× {{ line.quantity }}</text></view><view class="order-footer"><view><text class="muted">模拟实付</text><text class="price">¥{{ money(order.total) }}</text></view><AppButton v-if="order.status!=='已完成'" class="secondary compact" @click="shop.advance(order.id)">{{ order.status==='待发货'?'模拟发货 →':'确认模拟收货 ✓' }}</AppButton><text v-else class="completed-label">✓ 体验已完成</text></view></view>
      <view class="demo-tools"><text>清除本地演示订单，恢复所有库存</text><AppButton @click="resetConfirm=true">重置演示数据</AppButton></view>
    </view>

    <view class="site-footer"><view><text class="footer-brand">ShopPilot.</text><text>日常好物，认真挑选。</text></view><text>原创前端工程演示 / Chenxi DevLab<br>Vue 3 · TypeScript · uni-app · Pinia</text><AppButton @click="backToPortfolio">探索更多作品 ↗</AppButton></view>
    <view class="mobile-nav"><AppButton :class="{active:screen==='catalog'||screen==='product'}" @click="home"><text>⌂</text>发现</AppButton><AppButton :class="{active:screen==='cart'||screen==='checkout'}" aria-label="底部购物袋" @click="go('cart')"><text>♧ <text class="mobile-count">{{ cartCount||'' }}</text></text>购物袋</AppButton><AppButton :class="{active:screen==='orders'}" @click="go('orders')"><text>▤</text>订单</AppButton></view>
    <view v-if="resetConfirm" class="modal-backdrop"><view class="modal" role="dialog" aria-modal="true" aria-label="重置演示数据"><text class="title">重新开始这次体验？</text><text>将清除当前设备的购物袋与模拟订单，并恢复商品库存。</text><AppButton class="primary" @click="resetDemo">确认重置</AppButton><AppButton class="secondary" @click="resetConfirm=false">保留我的记录</AppButton></view></view>
  </view>
